"""Create comparisons and a report from actual expanded runs, without editing sources."""
import csv,json,sys,hashlib,subprocess,platform
from pathlib import Path
P=Path(__file__).resolve().parent;ROOT=P.parents[1]
read=lambda p:list(csv.DictReader(Path(p).open()))
def dump(n,rows):
 keys=list(dict.fromkeys(k for r in rows for k in r))
 with (P/n).open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=keys,lineterminator='\n');w.writeheader();w.writerows(rows)
def run(engine,source):
 cfg=json.loads((P/'N3_Expansion_Inputs.json').read_text());A=read(P/'N3_Expansion_Annual.csv');by={(r['case'],int(r['year'])):r for r in A};checks=json.loads((P/'N3_Expansion_Checks.json').read_text());assert checks['status']=='PASS_CHANGED_COMPONENTS'
 F=[r for r in read(engine/'handoff/f-common-endoflife-finalization-20261121/Annual.csv') if r['case']=='LATEST_F'];fb={int(r['year']):r for r in F}
 before=read(source/'handoff/claude-n3-model-draft-20261121/SPE_N3_Medical_Annual_DRAFT_20261121.csv');ob={(r['case'],int(r['year'])):r for r in before}
 comparison=[]
 metrics=['real_gdp_trn','nominal_gdp_trn','population','household_consumption_nominal_proxy_trn','I_policy_real_trn','capital_total_real_trn','macro_cash_DI_proxy_trn','tax_diagnostic_trn','household_cash_delta_trn','consolidated_partial_balance_proxy_trn','dividend_delta_trn','premium_relief_trn','pension_benefit_delta_trn']
 for r in A:
  cid=r['case'];y=int(r['year']);sq=by['SQ_COMMON_ON',y]
  for k in metrics:
   val=float(r[k]) if r.get(k) not in [None,''] else None;fixed=float(fb[y][k]) if fb[y].get(k) not in [None,''] else None;ref=float(sq[k]) if sq.get(k) not in [None,''] else None
   comparison.append(dict(case=cid,year=y,metric=k,absolute_value=val,common_ON_SQ=ref,difference_vs_common_ON_SQ=None if val is None or ref is None else val-ref,F_fixed_reference=fixed,difference_vs_F=None if val is None or fixed is None else val-fixed,unit='persons' if k=='population' else 'trillion_yen',comparison_scope='PARTIAL_CANDIDATE;F_VAT_HEALTH_CONNECTION_DIFFERS;NOT_CAUSAL_PACKAGE_RANKING'))
 dump('N3_SQ_F_Comparison.csv',comparison)
 interpolation=[]
 for y in range(2033,2039):
  a=by['MED_RATE_INTERPOLATION',y];b=by['N3_MED_50_CAP_SAME',y]
  interpolation.append(dict(year=y,patient_RATE=float(a['patient_payment_delta_trn']),patient_AMOUNT=float(b['patient_payment_delta_trn']),patient_difference=float(a['patient_payment_delta_trn'])-float(b['patient_payment_delta_trn']),cash_RATE=float(a['household_cash_delta_trn']),cash_AMOUNT=float(b['household_cash_delta_trn']),financing_tax_RATE=float(a['medical_financing_tax_trn']),financing_tax_AMOUNT=float(b['medical_financing_tax_trn']),GDP_RATE=float(a['real_gdp_trn']),GDP_AMOUNT=float(b['real_gdp_trn']),GDP_difference=float(a['real_gdp_trn'])-float(b['real_gdp_trn']),status='TWO_UNDECIDED_INTERPOLATION_CANDIDATES'))
 dump('Medical_Interpolation_Comparison.csv',interpolation)
 interactions=[]
 for y in range(2026,2056):
  for k in ['real_gdp_trn','tax_diagnostic_trn','household_consumption_nominal_proxy_trn']:
   combined=float(by['TAX_AND_PENSION',y][k]);single_tax=float(by['FLAT_HH_SURVEY',y][k]);single_pen=float(by['PENSION75_PROTECTED2033',y][k]);sq=float(by['SQ_COMMON_ON',y][k])
   interactions.append(dict(year=y,metric=k,combined_minus_SQ=combined-sq,single_effect_sum=single_tax+single_pen-2*sq,interaction=combined-single_tax-single_pen+sq,method='PAIRED_SOLVED_PATHS_NOT_ADDITIVE_ATTRIBUTION'))
 dump('Component_Interactions.csv',interactions)
 statuses=[('医療負担額/率補間','CONNECTED','候補2方式を2033–2038年並走','N3_Claim_Candidate_Audit.csv'),('消費税0/.25/.75数量弾力性・転嫁率.6/.8/1','EXPERIMENTAL','課税取引量と税収へ接続。独立した実消費数量→GDP経路は未接続','N3_VAT_Regular_Quantity.csv'),('医療財源','EXPERIMENTAL','F由来4配分、税保険料配分、部分準備資産を比較。全国債務OPEN','N3_Expansion_Annual.csv'),('給与/事業30・金融20・全控除廃止','EXPERIMENTAL','既存調査所得階層＋仮定源泉構成。年金所得扱い・地方税は未変更/OPEN','N3_Income_Distribution.csv'),('法人20・条件付き16','EXPERIMENTAL','利益GDP比/企業分布/基準実効率は仮定。消費税20は既存VAT経路に一度のみ','N3_Corporate_Accounts.csv'),('相続贈与40','OPEN','税源・従前税負担不足。税率インターフェース、年次税収null','N3_Policy_Accounts.csv'),('75歳開始・半官営拠出積立','EXPERIMENTAL','既存受給者保護、5歳階級内一様、拠出振替、利回り0/2/4候補','N3_Pension_Accounts.csv'),('500万円以下の減免・現物給付','EXPERIMENTAL','世帯年収を暫定単位、減免15/35%、現物3万円は未裁定','N3_Income_Distribution.csv'),('EITC廃止','OPEN','比較SQの独立EITC基準額が無いため廃止額を作らない','N3_Policy_Accounts.csv'),('公務員正規化・新規雇用','EXPERIMENTAL','10万人・年収300→400万円等は候補。正規化と純増労働を区別','N3_Expansion_Annual.csv'),('外国人材','STRUCTURE_ONLY','N4・地域配分・外部GDP比の条件関数を実行。GDP比定義OPENで追加人口は未接続','N3_Structural_Interfaces.csv'),('共済10–15ブロック','STRUCTURE_ONLY','範囲検査を実装。費用/給付差不明','N3_Structural_Interfaces.csv'),('スマートシュリンク','STRUCTURE_ONLY','密度/生産性/費用の仮定入力で優先順位計算。財源/投資GDPは未接続','N3_Structural_Interfaces.csv'),('インボイス簡素化','STRUCTURE_ONLY','時間×単価の関数試験。全国対象/時間が無く年次効果null','N3_Expansion_Checks.json'),('KPI自動修正','EXPERIMENTAL','2035以降の前年成長率0%未満候補で15%凍結をラッチ。正式自動裁定ではない','N3_Structural_Interfaces.csv'),('N3全政策・全国PB/国債・健康/QOL','NOT_IMPLEMENTED','部分実装。全国財政・因果較正・健康評価を認定しない','N3_Expansion_Annual.csv')]
 dump('Implementation_Status.csv',[dict(item=i,status=s,boundary=b,artifact=f) for i,s,b,f in statuses])
 # Retain old outputs at their pinned paths, with byte identity rather than copies.
 sources=[]
 for commit,folder,names in [('3c77eafc2073fdaba4c129164817d2f57c9421b9','handoff/claude-n3-model-draft-20261121/',['SPE_N3_Medical_Annual_DRAFT_20261121.csv','SPE_N3_Medical_Common_DRAFT_20261121.csv','SPE_N3_Medical_vs_SQ_Common_On_DRAFT_20261121.csv']),('31d659e573811a2e189350bee08cd5efc2c2c433','handoff/chatgpt-n3-draft-independent-verification-20261121/',['Independent_Result.json','SPE_N3_Draft_ChatGPT_Independent_Verification_DRAFT_20261121.md']),('64f2a317e6e9827e37346ad80de7cc0649357c05','handoff/n3-model-expansion-work-20261121/',['SPE_Work_N3_Model_Expansion_Execution_Instruction_20261121.md']),('5804388482864af08204ba0d0e76a46206dacdbd','policies/',['New3linesPolicies.md','FreedomPolicies.md','FreedomPolicies_Annex.md'])]:
  for name in names:
   path=folder+name;b=subprocess.check_output(['git','-C',str(ROOT),'show',commit+':'+path]);sources.append(dict(commit=commit,path=path,size=len(b),sha256=hashlib.sha256(b).hexdigest(),use='PINNED_ORIGINAL_READ_ONLY_NO_DUPLICATE_COPY'))
 for path in ['handoff/f-household-social-20261120/Inputs.json','handoff/f-household-social-20261120/Sources_and_Map.md','handoff/f-pension-policy-20261120/Inputs.json','handoff/f-common-endoflife-finalization-20261121/Inputs.json']:
  b=(engine/path).read_bytes();sources.append(dict(commit=cfg['engine_commit'],path=path,size=len(b),sha256=hashlib.sha256(b).hexdigest(),use='SURVEY_INPUT_AND_COMMON_DEPENDENCY'))
 (P/'Source_Reuse.json').write_text(json.dumps(dict(originals=sources,reused_old_PASS='Claude8 originals;ChatGPT25920 claim boundaries/26385 independent cells;fixed ff621006 common engine Claude verification4924c8e;not new independent verification of expansions'),ensure_ascii=False,indent=2)+'\n')
 focus=['SQ_COMMON_ON','N3_MED_50_CAP_SAME','MED_RATE_INTERPOLATION','FLAT_HH_SURVEY','CORPORATE_AND_PROFIT','PENSION75_PROTECTED2033','RELIEF35_INKIND','PUBLIC_REGULARIZE100K','PUBLIC_ADD100K','N3_CONNECTED_COMPONENTS_A','N3_CONNECTED_COMPONENTS_B','FLAT_RELIEF_PHASE1_2030','N3_CONNECTED_PHASE1_2030']
 lines=['# SPE｜N3共通エンジン拡張・年次再計算 実行報告','', '**DRAFT / NON-CANONICAL｜2026-11-21 JST**', '', '## 実行成果と以前からの進歩', '', '固定指示64f2a317…に従い、既存14条件を保持し新規32条件を追加、46条件×2026–2055年＝1,380年次行を実行した。所得階層課税・企業税/優遇/投資/配当・75歳開始/拠出振替/積立・保険料減免/現物給付・公務員給与/追加労働が、既存SQ年次エンジンの家計現金、直接税、政府費用、サービス付加価値、投資、労働へ実接続された。新しいGDP差は保存GDPへの足算ではなく、消費/投資の平滑化、供給上限、資本蓄積、税反応を再実行した結果。', '', '新コードは新規ディレクトリだけに置き、固定N3/F/SQ・政策原本を上書きしていない。企業利益率・企業分布・所得源泉構成・年金適用範囲・利回り・雇用人数等、原文にない数値は未較正の感度候補。N3_FULLというケースは作っていない。外国人材追加人口、相続税ベース、EITC基準、全国財政はOPENであり、全政策完成ではない。', '', '## 主要年次結果', '', '兆円。税は全国予測ではなく固定基準＋仮定税源に基づく診断/代理。併用A/Bは採用値や中央予測ではない。', '', '|条件|2035実質GDP|2040実質GDP|2055実質GDP|2055 SQ差|2055政策税差代理|','|---|---:|---:|---:|---:|---:|']
 for cid in focus:
  r=by[cid,2055];lines.append('|'+cid+'|'+'|'.join(f"{float(by[cid,y]['real_gdp_trn']):.6f}" for y in [2035,2040,2055])+f"|{float(r['real_gdp_trn'])-float(by['SQ_COMMON_ON',2055]['real_gdp_trn']):+.6f}|{float(r['policy_tax_delta_trn']):+.6f}|")
 lines += ['', 'FLAT_HHの大きな税収増とGDP減は、全控除を使わず調査総所得の仮定源泉構成へ30%/20%を掛け、既存平均税を按分した差による。この源泉構成は観測個票ではなく、財務省の全国税収推計でもない。大きな差をN3効果の頑健な予測と解釈しない。income_scale .90/1.04/1.15、企業利益GDP比5/10%等で幅を示す。', '', '併用A＝医療率補間＋VAT経路/弾力性.25＋所得課税＋法人優遇（利益分母）＋2033到達コーホート年金＋減免/現物＋公務員正規化。Bは年金保護開始2039、投資比率の売上分母、医療財源の部分準備資産型に変更。Bとの差を単一施策の効果と呼ばない。単独/併用の差分差はComponent_Interactionsに保存し、限界差の足算を寄与分解にしない。', '', 'N3_SQ_F_Comparisonは年次の絶対値・SQ共通ON差・固定LATEST_Fとの差を別列に保存。F側は医療VAT数量・健康労働の接続範囲等が異なるため厳密な政策パッケージの因果順位にはしない。旧v5の493.7兆円に係数を合わせていない。', '', '原文フェーズ1（2026–2032）の税・減免開始に対応し、2030開始・3年移行のFLAT_RELIEF_PHASE1_2030とN3_CONNECTED_PHASE1_2030を追加。年2030と補間形状は未裁定候補。従前44条件の税・減免2033開始は遅延感度として保持し、原文のフェーズ1を再現したとは扱わない。年金は2033–2038、企業優遇の開始は2033候補のまま。', '', '## 医療・VATの4留保', '', '1. 負担額補間を旧ケースとして保持し、率補間後に上限を適用するMED_RATE_INTERPOLATIONを追加。1,728の請求境界を別閉形式で検査し、2033–2038年の患者・財源税・現金・GDPをMedical_Interpolation_Comparisonに出力。どちらも未裁定。', '2. 家計現金は正＝現金増、患者負担は正＝負担増。絶対値とSQ共通ON差を区別。2055年旧5割・上限維持の家計現金は絶対−1.785603兆円、SQ差−1.772548兆円（旧表−1.79は絶対額）。所得階層のDIも基準/税・減免後の代理値を別列化し、現物の支出代替分を現金所得と区別した。', '3. VAT弾力性0を保持し.25/.75、転嫁率.6/.8/1の感度を実行。非ゼロの取引数量と税収は変わるが、既存基盤の家計価格/企業所得配分は固定数量の式で、独立した数量→実消費→GDP経路は未接続。医療数量→VAT税源も未接続。これを完全な増税需要モデルとは呼ばない。', '4. 医療財源はF由来50%×4分配を維持し、税/保険料型・部分政策準備資産型を追加。債発行/償還/準備資産/未配賦を年次出力。準備資産は全国債務返済ではない。新規政策税・政府費用・保険者収支は別勘定で、未閉鎖をpolicy_budget_unclosedへ残す。', '', '|VAT候補|2055VAT収入|2055GDP|','|---|---:|---:|']
 for cid in ['N3_VAT_PATH_ONLY','VAT_ELASTIC_025','VAT_ELASTIC_075','VAT_PASS_060_EL025','VAT_PASS_100_EL025']:
  r=by[cid,2055];lines.append(f"|{cid}|{float(r['modeled_VAT_trn']):.6f}|{float(r['real_gdp_trn']):.6f}|")
 lines += ['', '数量弾力性のみを変えた3ケースのGDPが同じなのは、数量の家計需要経路がまだ無いことを実測した結果であり、ゼロの経済効果を立証したものではない。価格転嫁率を変えたケースは既存価格・所得経路からGDPへ波及する。', '', '## 新規施策の実装境界', '', '|施策|状態|境界|','|---|---|---|']
 for item,status,boundary,artifact in statuses:lines.append('|'+item+'|'+status+'|'+boundary+'|')
 lines += ['', '所得分布は固定F基盤に保存済みの国民生活基礎調査の所得階級29セル・五分位別税/保険料を再利用。人口÷2.22で世帯数を代理化、所得源泉構成は非高齢/高齢の構成比に仮定を置く。給与・事業30と金融20のみ接続し、年金所得税の再設計・地方税はOPEN/従来扱い。法人は固定SQ名目経路×仮定利益比率であり、実際の法人課税ベースを発見したという主張はしない。相続・贈与40の年次税額はnull。消費税は既存経路だけに入り、フラット税の20%区分として再加算しない。', '', '年金は2033–2038移行、2039以降の定着を候補入力で扱う。2033又は2039以降に65歳へ達するコーホートだけ75歳まで受給を遅らせ、以前の受給者の給付を一括停止しない。年齢5歳階級内一様、給付額は既存の代表例を人口へ適用した候補。既存拠出の一部を半官営基金へ振り替え、家計保険料へ二度引かない。公的制度の拠出減を勘定に計上し、基金の拠出・利息・給付・資産を別に追う。既存DBと新積立の財政/給付設計を閉鎖したものではない。利回りの相手方は域外金融所得としてOPEN。', '', '企業は配当性向60%以上と投資20%以上のANDを実装。投資の分母は利益/売上の2候補。優遇減税の使途は投資30%・配当40%・残余内部留保という候補配分で、追加配当の金融所得税20%を別計上。元のF企業優遇を有効にせず、N3の差額だけ既存資本経路へ入れる。', '', '減免は500万円以下を暫定的に世帯年収へ適用した感度。個人単位の制度が確定したとはしない。EITCの比較基準額は無く廃止の追加益を作らない。正規化は給与差だけで新規雇用0、追加雇用ケースだけ労働を増やし、人口は増やさない。外国人材はN4・地域重み・外部比率の関数を実行するが、GDP比5%の意味を勝手に人数上限へ換算せず、N3追加人口は全ケース未接続。共有SQの移入を重複して追加していない。', '', '制度インターフェースは共済10–15の妥当性、地域密度×生産性/費用の優先順位、インボイス作業時間×単価、KPI成長率候補を実際に評価する。数量や財源の無い制度を全国GDP効果へ置換しない。', '', '## 検証', '', f"旧14条件の非空元列 {checks['checks']['old14_case_numeric_regression_cells']:,}セル、固定SQ共通ON180セルが一致。新請求境界1,728、共通保護/供給1,380行、企業AND/使途720行、年金保護/ストック270行、所得階層閾値/DI/現金10,440行、VAT数量4,140行、VAT＋政策税の一度だけ計上1,380行を確認。", '', f"{len(checks['deterministic_replay'])}生成出力を別一時ディレクトリで再実行し実バイト一致。固定N3/F作業treeはgit statusで不変更を確認。以前の25,920請求/26,385独立照合PASSは固定版の範囲で再利用し、新拡張の独立検算済みとは呼ばない。今回の検査は実装者による変更箇所の自動検査。", '', '## 残課題・状態', '', '生成・年次実行・ローカル検証は完了。原本格納と固定Commit事後取得はDelivery_Verification.jsonに別記。照合成立後のみCUSTODY PASS。外国人材追加の人口接続、相続税源、EITC基準、個人源泉分布、完全な半官営保険、共済の費用/給付、スマートシュリンク資本支出、インボイス全国コスト、健康/QOL、全国PB/国債・保険運用・金融所得の相手方はOPEN/未実装。候補値は正式採用していない。', '', '今回完了したのは「接続できたN3部品の実装・年次再計算・比較・引渡し」であり、N3全政策の完成や財政自律の達成ではない。未裁定の部分だけ感度/OPENとして残し、追加承認・独立レビューを進行条件へ追加していない。RP-023/M19–25 HOLD、RP-024 PENDING、政策原文・正式承認状態を維持した。', '']
 (P/'SPE_N3_Model_Expansion_Report_DRAFT_20261121.md').write_text('\n'.join(lines))
 print(json.dumps(dict(report='GENERATED',annual_rows=len(A),cases=len({r['case'] for r in A}),reference_and_policy_status='DRAFT_NON_CANONICAL')))
